type RecordItem = {
    id: string;
    status: string;
};
export function paginateFilteredRecords(records: RecordItem[], page: number, pageSize: number, statusFilter: string | null): unknown {
    if (!Number.isInteger(page) || page < 1 || !Number.isInteger(pageSize) || pageSize < 1 || pageSize > 100)
        throw new Error('Invalid pagination');
    const filtered = statusFilter === null ? records : records.filter(row => row.status === statusFilter);
    const total = filtered.length;
    return {
        items: filtered.slice((page - 1) * pageSize, page * pageSize),
        page, pageSize, total, totalPages: Math.ceil(total / pageSize)
    };
}
